agentops:index/incidentPipeline:Incident.description:
An incident pipeline (incident workflow): routes inbound alerts from a provider to an orchestrator agent and its specialist agents, optionally delivering summaries to Slack.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as agentops from "@pulumi/agentops";

// Self-contained incident pipeline: Terraform deploys the orchestrator from the
// worker catalog, creates the specialist agents (and their LLM credential), then
// wires them into the pipeline. No pre-existing IDs required. Each agent's
// `customer` (tenant) is derived from your account by the server.
// The specialists' LLM key. credential_ref resolves this credential by NAME, so
// the key must match the provider of the `model` each agent runs (an Anthropic
// key for the claude-sonnet-5 model below).
const specialistLlmKey = new agentops.Credential("specialist_llm_key", {
    name: "specialist-llm-key",
    value: specialistLlmKeyConfig,
});
// ── Orchestrator: deployed from the worker catalog ───────────────────────────
// The "orchestrator" catalog entry pins the image and uses the managed AgentOps
// LLM gateway, so the customer and credentials are derived server-side — you only
// name the instance.
const orchestrator = new agentops.WorkerCatalogDeployment("orchestrator", {
    catalogId: "orchestrator",
    agentId: "incident-orchestrator",
    displayName: "Incident Orchestrator",
});
// ── Specialists the orchestrator delegates to ────────────────────────────────
const dbSpecialist = new agentops.HostedAgent("db_specialist", {
    agentId: "incident-db-specialist",
    instructions: "Investigate database-related incidents.",
    credentialRef: specialistLlmKey.name,
    model: "claude-sonnet-5",
});
const netSpecialist = new agentops.HostedAgent("net_specialist", {
    agentId: "incident-net-specialist",
    instructions: "Investigate networking-related incidents.",
    credentialRef: specialistLlmKey.name,
    model: "claude-sonnet-5",
});
// ── Webhook endpoint that feeds alerts into the pipeline ─────────────────────
// A standalone webhook trigger (no target); the pipeline consumes it via
// trigger_id. An endpoint must be linked before the pipeline can be activated.
const incidentsEndpoint = new agentops.Trigger("incidents_endpoint", {
    name: "incident-alerts",
    description: "Inbound alert webhook for the staging incident pipeline",
});
// ── Pipeline wiring the agents together ──────────────────────────────────────
const incidents = new agentops.IncidentPipeline("incidents", {
    name: "staging-incidents",
    status: "active",
    triggerId: incidentsEndpoint.id,
    alertSource: {
        provider: "generic",
        monitorMode: "create_catchall",
    },
    routingRule: {
        environment: "staging",
        severity: "critical",
    },
    orchestratorBinding: {
        agentId: orchestrator.runtimeAgentId,
    },
    specialistBindings: [
        {
            agentId: dbSpecialist.runtimeAgentId,
            role: "database",
            enabled: true,
        },
        {
            agentId: netSpecialist.runtimeAgentId,
            role: "networking",
            enabled: true,
        },
    ],
});
